const REQUEST_TYPES = {
  overtime:   { label:"Overtime",        color:"#1E3A6E", bg:"#E8EDF6", icon:"⏱" },
  offset:     { label:"Offset",          color:"#1DB584", bg:"#E6F9F3", icon:"⇄"  },
  leave:      { label:"Leave",           color:"#E8913A", bg:"#FDF3E7", icon:"🗓" },
  dutyDayOff: { label:"Duty on Day-Off", color:"#C8102E", bg:"#FBE3E6", icon:"📋" },
};
const STATUS_STYLE = {
  pending:  { color:"#B07D2A", bg:"#FEF9EC", label:"Pending"  },
  approved: { color:"#1A7F56", bg:"#E8F8F2", label:"Approved" },
  rejected: { color:"#A30E26", bg:"#FBE3E6", label:"Rejected" },
};
const TYPE_KEYS = ["overtime","offset","leave","dutyDayOff"];
// Balance pools tracked: Overtime and Duty on Day-Off are stored SEPARATELY
// (creditsOvertime, creditsDutyOff) but DISPLAYED as one merged "credits" total
// on the dashboard. Offset draws down from that combined total (OT first, then
// Duty) and is tracked separately as a running "used" total. Leave is independent.
const BALANCE_TYPES = {
  credits:    { label:"OT/Duty on Day-Off Credits", color:"#1E3A6E", bg:"#E8EDF6", icon:"⏱" },
  offsetUsed: { label:"Offset Used",        color:"#1DB584", bg:"#E6F9F3", icon:"⇄"  },
};
const BALANCE_KEYS = ["credits","offsetUsed"];
// Helper: merged credits total from the two separately-tracked pools
function creditsTotal(bal){ return (bal?.creditsOvertime||0) + (bal?.creditsDutyOff||0); }
// Leave balance helpers
function leaveRemaining(bal, leaveTypeId){ return Math.max(0, bal?.leaveBalances?.[leaveTypeId] ?? 0); }
function totalLeaveRemaining(bal){
  const m = bal?.leaveBalances || {};
  return Object.values(m).reduce((s,v)=>s+(v||0),0);
}
const DEPARTMENTS = [
  "Admin",
  "Operations",
  "DRRM Operations",
  "Rescue and Response",
  "Logistics",
  "Training",
  "Rescue",
  "IT",
];

// ─── HELPERS ──────────────────────────────────────────────────────────────────
function genId(p){ return `${p}${Date.now()}${Math.floor(Math.random()*100)}`; }
function today(){ return new Date().toISOString().split("T")[0]; }
function fmt(h){ return `${h%1===0?h.toFixed(0):h.toFixed(1)}h`; }
function fmtDays(d){ const n=+d||0; return `${n%1===0?n.toFixed(0):n.toFixed(1)} day${n===1?"":"s"}`; }
function hoursBetween(start, end){
  if(!start||!end) return 0;
  const [sh,sm]=start.split(":").map(Number);
  const [eh,em]=end.split(":").map(Number);
  let mins=(eh*60+em)-(sh*60+sm);
  if(mins<0) mins+=24*60; // cross-midnight
  return Math.round((mins/60)*10)/10;
}
function reqDurationText(r, leaveTypes){
  if(r.type==="leave"){
    const lt = leaveTypes?.find(l=>l.id===r.leaveTypeId);
    return `${lt?lt.name:"Leave"} · ${fmtDays(r.days||0)}`;
  }
  if(r.startTime && r.endTime) return `${r.startTime}–${r.endTime} (${fmt(r.hours||0)})`;
  return fmt(r.hours||0);
}
function fmtDate(d){
  if(!d) return "—";
  const [y,m,day]=d.split("-");
  return `${["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][+m-1]} ${+day}, ${y}`;
}
function dateRangeText(r){
  if(r.endDate && r.endDate!==r.date) return `${fmtDate(r.date)} – ${fmtDate(r.endDate)}`;
  return fmtDate(r.date);
}
function nowStamp(){
  const n=new Date();
  return n.toLocaleDateString("en-PH",{year:"numeric",month:"long",day:"numeric"})+
    " · "+n.toLocaleTimeString("en-PH",{hour:"2-digit",minute:"2-digit"});
}
function monthLabel(ym){ // "2025-06" → "June 2025"
  if(!ym) return "";
  const [y,m]=ym.split("-");
  return `${["January","February","March","April","May","June","July","August","September","October","November","December"][+m-1]} ${y}`;
}

// ─── BASE UI ──────────────────────────────────────────────────────────────────
function Avatar({initials,size=36}){
  const c=["#1E3A6E","#1DB584","#E8913A","#C8102E","#3A8ED9"][(initials.charCodeAt(0)+initials.charCodeAt(1))%5];
  return <div style={{width:size,height:size,borderRadius:"50%",background:c,color:"#fff",fontWeight:700,
    fontSize:size*0.36,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{initials}</div>;
}
function Badge({status}){
  const s=STATUS_STYLE[status];
  return <span style={{background:s.bg,color:s.color,borderRadius:20,padding:"3px 10px",fontSize:12,fontWeight:600}}>{s.label}</span>;
}
function TypeChip({type}){
  const t=REQUEST_TYPES[type];
  return <span style={{background:t.bg,color:t.color,borderRadius:20,padding:"3px 10px",fontSize:12,fontWeight:600}}>{t.icon} {t.label}</span>;
}
function Card({children,style={}}){
  return <div style={{background:"#fff",borderRadius:14,padding:"20px 24px",
    boxShadow:"0 1px 4px rgba(0,0,0,0.07),0 0 0 1px rgba(0,0,0,0.04)",...style}}>{children}</div>;
}
function Btn({children,onClick,variant="primary",disabled,style={},size="md"}){
  const base={border:"none",borderRadius:9,cursor:disabled?"not-allowed":"pointer",fontWeight:600,
    fontFamily:"inherit",transition:"all .15s",opacity:disabled?0.5:1,outline:"none",
    padding:size==="sm"?"6px 14px":"10px 20px",fontSize:size==="sm"?13:14};
  const v={primary:{background:"#1E3A6E",color:"#fff"},success:{background:"#1DB584",color:"#fff"},
    danger:{background:"#C8102E",color:"#fff"},ghost:{background:"#F4F5F7",color:"#444"},
    outline:{background:"#fff",color:"#1E3A6E",boxShadow:"0 0 0 1.5px #1E3A6E"},
    dark:{background:"#1a1a1a",color:"#fff"},teal:{background:"#0D9488",color:"#fff"}};
  return <button onClick={disabled?undefined:onClick} style={{...base,...v[variant],...style}}>{children}</button>;
}
function Inp({label,...p}){
  return <div style={{display:"flex",flexDirection:"column",gap:5}}>
    {label&&<label style={{fontSize:13,fontWeight:600,color:"#555"}}>{label}</label>}
    <input {...p} style={{border:"1.5px solid #E2E5EA",borderRadius:9,padding:"9px 13px",fontSize:14,
      fontFamily:"inherit",color:"#1a1a1a",background:"#FAFAFA",outline:"none",
      width:"100%",boxSizing:"border-box",...p.style}}/>
  </div>;
}
function Sel({label,children,...p}){
  return <div style={{display:"flex",flexDirection:"column",gap:5}}>
    {label&&<label style={{fontSize:13,fontWeight:600,color:"#555"}}>{label}</label>}
    <select {...p} style={{border:"1.5px solid #E2E5EA",borderRadius:9,padding:"9px 13px",fontSize:14,
      fontFamily:"inherit",color:"#1a1a1a",background:"#FAFAFA",outline:"none",
      width:"100%",boxSizing:"border-box"}}>{children}</select>
  </div>;
}
function Txtarea({label,...p}){
  return <div style={{display:"flex",flexDirection:"column",gap:5}}>
    {label&&<label style={{fontSize:13,fontWeight:600,color:"#555"}}>{label}</label>}
    <textarea {...p} style={{border:"1.5px solid #E2E5EA",borderRadius:9,padding:"9px 13px",fontSize:14,
      fontFamily:"inherit",color:"#1a1a1a",background:"#FAFAFA",outline:"none",
      width:"100%",boxSizing:"border-box",resize:"vertical",minHeight:80,...p.style}}/>
  </div>;
}
function SectionLabel({children}){
  return <p style={{margin:"0 0 12px",fontSize:12,fontWeight:700,color:"#999",
    textTransform:"uppercase",letterSpacing:"0.08em"}}>{children}</p>;
}

